1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerCityCapacityException;
8	
9	/**
10	 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 409 via
11	 * {@link OwnerCityCapacityException} when the owner's city already contains the maximum number of
12	 * owners ({@value #MAX_OWNERS_PER_CITY}); the city is compared case-insensitively with surrounding
13	 * whitespace trimmed. The new owner is still unsaved, so it is not counted against the limit.
14	 */
15	public class CheckOwnerCityCapacity {
16	
17	    /** A city may hold at most this many owners; the create of one more is rejected. */
18	    static final int MAX_OWNERS_PER_CITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerCityCapacityException {
22	        String city = request.getCity();
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (equalsNormalized(city, existing.getCity())) {
26	                count++;
27	            }
28	        }
29	        if (count >= MAX_OWNERS_PER_CITY) {
30	            throw new OwnerCityCapacityException(city, count);
31	        }
32	    }
33	
34	    private static boolean equalsNormalized(String a, String b) {
35	        if (a == null || b == null) {
36	            return a == null && b == null;
37	        }
38	        return a.trim().equalsIgnoreCase(b.trim());
39	    }
40	}
